const assert = require('node:assert/strict'), fs = require('node:fs'), path = require('node:path');
const { createRequire } = require('node:module');
const web = createRequire(path.resolve(__dirname, '../web/package.json'));
const source = fs.readFileSync(path.join(__dirname, '../web/src/features/RelayAttachmentStorage.model.ts'), 'utf8');
const compiled = web('esbuild').transformSync(source, { loader: 'ts', format: 'cjs', target: 'es2022' });
const mod = { exports: {} };
new Function('module', 'exports', compiled.code)(mod, mod.exports);
const { readRelayStorage, canUseStorageAction, googleConsentURL, storageBytes } = mod.exports;
const base = () => ({ can_admin: true, configured: true, connected: true, state: 'connected', local: { files: 4, bytes: 1024 }, remote: { files: 2, bytes: 512 }, pending: { files: 2, bytes: 512 }, remote_only_files: 0, migration: { running: false, files: 0, bytes: 0, total_files: 0, total_bytes: 0 } });
for (const state of ['local', 'not_configured', 'connected', 'migrating', 'needs_reconnect', 'offline']) assert.equal(readRelayStorage({ ...base(), state }).state, state);
const status = readRelayStorage(base());
assert.equal(canUseStorageAction(status, 'move'), true);
assert.equal(canUseStorageAction(status, 'disconnect'), false);
assert.equal(canUseStorageAction({ ...status, remote: { files: 0, bytes: 0 } }, 'disconnect'), true);
assert.equal(canUseStorageAction(status, 'connect'), false);
assert.equal(canUseStorageAction({ ...status, remote_only_files: 1 }, 'disconnect'), false);
assert.equal(canUseStorageAction({ ...status, migration: { ...status.migration, running: true } }, 'disconnect'), false);
assert.equal(canUseStorageAction({ ...status, migration: { ...status.migration, running: true } }, 'move'), false);
assert.equal(canUseStorageAction({ ...status, state: 'needs_reconnect', migration: { ...status.migration, running: true } }, 'connect'), true, 'an interrupted migration can reconnect its account');
assert.equal(canUseStorageAction({ ...status, state: 'offline' }, 'move'), true, 'a linked offline account can retry after provider recovery');
assert.equal(canUseStorageAction({ ...status, remote_only_files: 0, remote: { files: 1, bytes: 1 } }, 'disconnect'), false, 'retained Drive objects still need their account for cleanup');
for (const action of ['connect', 'move', 'disconnect']) assert.equal(canUseStorageAction({ ...status, can_admin: false }, action), false);
assert.equal(canUseStorageAction({ ...status, connected: false, configured: false }, 'connect'), false);
assert.equal(canUseStorageAction(readRelayStorage({ ...base(), remote: { files: 0, bytes: 0 }, pending: { files: 0, bytes: 0 } }), 'move'), true, 'existing local attachments can move before any queue rows exist');
assert.equal(canUseStorageAction({ ...status, local: { files: 0, bytes: 0 }, pending: { files: 0, bytes: 0 } }, 'move'), false);
for (const malformed of [null, [], {}, { ...base(), connected: 'yes' }, { ...base(), state: 'guess' }, { ...base(), local: { files: -1, bytes: 1 } }, { ...base(), pending: { files: 1.5, bytes: 1 } }, { ...base(), remote_only_files: NaN }, { ...base(), remote: { files: 1, bytes: Number.MAX_SAFE_INTEGER + 1 } }]) assert.throws(() => readRelayStorage(malformed));
const consent = process.env.AGENTNET_RELAY_CONSENT_URL || 'https://accounts.google.com/o/oauth2/v2/auth?client_id=public&state=synthetic';
assert.equal(googleConsentURL(consent), consent);
for (const bad of ['http://accounts.google.com/o/oauth2/v2/auth', 'https://accounts.google.com.evil.test/o/oauth2/v2/auth', 'https://user@accounts.google.com/o/oauth2/v2/auth', 'https://accounts.google.com:444/o/oauth2/v2/auth', 'https://accounts.google.com/o/oauth2/v2/auth#token', 'https://accounts.google.com/o/oauth2/v2/auth?client_secret=secret', 'https://accounts.google.com/o/oauth2/v2/auth?access_token=secret', 'javascript:alert(1)', 'mailto:a@b.test', '//accounts.google.com/o/oauth2/v2/auth']) assert.equal(googleConsentURL(bad), '');
assert.equal(readRelayStorage({ ...base(), consent_url: consent }).consent_url, undefined, 'GET never grants a consent link');
assert.equal(readRelayStorage({ ...base(), consent_url: consent }, true).consent_url, consent);
const member = readRelayStorage({ ...base(), can_admin: false, account: { email: 'ADMIN_PRIVATE', name: 'ADMIN_PRIVATE' }, folder: { id: 'PRIVATE', name: 'PRIVATE' }, consent_url: consent, client_secret: 'SECRET', notice: 'PRIVATE_COUNT 123 files', remote_only_files: 12, migration: { running: true, files: 9, bytes: 123, total_files: 12, total_bytes: 256 } }, true);
assert.ok(!JSON.stringify(member).includes('PRIVATE') && !JSON.stringify(member).includes('SECRET'));
assert.equal(member.consent_url, undefined);
assert.equal(member.notice, undefined);
assert.deepEqual([member.local, member.remote, member.pending], Array.from({ length: 3 }, () => ({ files: 0, bytes: 0 })));
assert.equal(member.remote_only_files, 0);
assert.deepEqual(member.migration, { running: false, files: 0, bytes: 0, total_files: 0, total_bytes: 0 });
assert.equal(storageBytes(1024), '1 KiB'); assert.equal(storageBytes(0), '0 B');
console.log('Relay storage model PASS: exact states/counts, admin-only mutations, remote-only/migration guards, safe external consent, no member account/credential disclosure');
